2	import { z } from "zod";
3	import { createClient } from "@/lib/supabase/server";
4	import { isAdminEmail } from "@/lib/utils";
5	import { runAgent } from "@/lib/agent";
6	
7	export const runtime = "nodejs";
8	export const dynamic = "force-dynamic";
9	// Agent calls can chain multiple tool invocations — raise from the default 10s.
10	export const maxDuration = 60;
11	
12	const AgentRequestSchema = z.object({
13	  prompt: z.string().min(1).max(8000),
14	  systemPrompt: z.string().max(8000).optional()
15	});
16	
17	/**
18	 * Admin-only entry point to the embedded Claude Agents SDK + Composio
19	 * Tool Router. Useful for on-demand ops: triage a lead, draft a follow-up,
20	 * create a Stripe customer/invoice, file a GitHub/Linear task, validate
21	 * Vercel env or a deployment status, etc.
22	 *
23	 * Heavier / long-running automations should run as `scripts/agent.ts` out
24	 * of band, since serverless has time limits even with maxDuration raised.
25	 */
26	export async function POST(request: Request) {
27	  const supabase = await createClient();
28	  const {
29	    data: { user }
30	  } = await supabase.auth.getUser();
31	
32	  if (!user || !isAdminEmail(user.email)) {
33	    return NextResponse.json({ error: "forbidden" }, { status: 403 });
34	  }
35	
36	  let body: unknown;
37	  try {
38	    body = await request.json();
39	  } catch {
40	    return NextResponse.json({ error: "invalid_json" }, { status: 400 });
41	  }
42	
43	  const parsed = AgentRequestSchema.safeParse(body);
44	  if (!parsed.success) {
45	    return NextResponse.json(
46	      { error: "invalid_input", details: parsed.error.flatten() },
47	      { status: 400 }
48	    );
49	  }
50	
51	  const result = await runAgent({
52	    userId: user.id,
53	    prompt: parsed.data.prompt,
54	    ...(parsed.data.systemPrompt ? { systemPrompt: parsed.data.systemPrompt } : {})
55	  });
56	
57	  if (!result.ok) {
58	    const status = result.error === "not_configured" || result.error === "sdk_not_installed" ? 503 : 500;
59	    return NextResponse.json({ ok: false, error: result.error }, { status });
60	  }
61	  return NextResponse.json({ ok: true, result: result.result, trace: result.trace });
62	}
