2	/**
3	 * Work-order server actions (Phase 3 — fully wired).
4	 *
5	 * Per PRODUCTION-PLAN §7.4. State machine (enforced in code via TRANSITIONS):
6	 *   open → quoted → accepted → in_progress → delivered → closed
7	 *     └──────┴──────────┴───────────┴────────────┴──→ cancelled
8	 * `closed` and `cancelled` are terminal. `cancelled` is reachable from any
9	 * non-terminal state. Both `quoteWorkOrder` and `updateWorkOrderStatus`
10	 * read current status first and reject illegal transitions.
11	 *
12	 * Notifications go through `lib/resend.ts` + `lib/resend-templates.ts`. Every
13	 * email send is wrapped so a Resend / DKIM failure cannot break the underlying
14	 * action (work order still progresses).
15	 *
16	 * Invoice model (LOCKED): accepting a quote ONLY flips the work order to
17	 * `accepted` (+ `accepted_at`). The Stripe invoice is created later by the
18	 * ADMIN via the "Create Stripe Invoice" button (→ `createInvoiceForWorkOrder`
19	 * in lib/actions/invoices.ts). There is intentionally no auto-invoice on
20	 * accept — `work_orders.project_id` was never set client-side, so that branch
21	 * was dead anyway.
22	 *
23	 * Attachment uploads are a two-step signed-URL flow:
24	 *   1. `submitWorkOrder` validates size + MIME, inserts the work order, and
25	 *      mints a signed upload URL per attachment (no row inserted yet).
26	 *   2. The client PUTs the bytes, then calls `finalizeWorkOrderAttachment`
27	 *      which inserts the `work_order_attachments` row pointing at the real
28	 *      object. Row-after-bytes means a failed PUT never leaves a dangling
29	 *      attachment row whose signed-download link 404s.
30	 */
31	import { revalidatePath } from "next/cache";
32	import { z } from "zod";
33	import { requireUser, requireAdmin, AuthError } from "@/lib/actions/auth";
34	import type { WorkOrderStatus } from "@/lib/database.types";
35	import { sendEmail } from "@/lib/resend";
36	import {
37	  workOrderReceivedToAdmin,
38	  workOrderQuoteSentToClient,
39	  workOrderAcceptedToAdmin,
40	  workOrderStatusChangedToClient
41	} from "@/lib/resend-templates";
42	import { cioTrack, isCustomerIoConfigured } from "@/lib/customerio";
43	import { createAdminClient } from "@/lib/supabase/server";
44	
45	/**
46	 * Allowed work-order status transitions. `closed`/`cancelled` are terminal
47	 * (empty arrays). `cancelled` is reachable from every non-terminal state.
48	 */
49	const TRANSITIONS: Record<WorkOrderStatus, readonly WorkOrderStatus[]> = {
50	  open: ["quoted", "cancelled"],
51	  quoted: ["accepted", "cancelled"],
52	  accepted: ["in_progress", "cancelled"],
53	  in_progress: ["delivered", "cancelled"],
54	  delivered: ["closed", "cancelled"],
55	  closed: [],
56	  cancelled: []
57	};
58	
59	function canTransition(from: WorkOrderStatus, to: WorkOrderStatus): boolean {
60	  return TRANSITIONS[from]?.includes(to) ?? false;
61	}
62	
63	const MAX_FILE_SIZE_BYTES = 25 * 1024 * 1024;
64	
65	const ALLOWED_MIME = new Set<string>([
66	  "image/png",
67	  "image/jpeg",
68	  "image/webp",
69	  "image/gif",
70	  "image/svg+xml",
71	  "application/pdf",
72	  "application/vnd.openxmlformats-officedocument.wordprocessingml.document",
73	  "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",
74	  "application/vnd.openxmlformats-officedocument.presentationml.presentation",
75	  "text/plain",
76	  "text/csv"
77	]);
78	
79	const uuid = z.string().uuid("invalid id");
80	const positiveInt = z
81	  .number()
82	  .int("must be an integer")
83	  .positive("must be > 0")
84	  .max(1_000_000_000, "absurdly large");
85	
86	const submitInput = z.object({
87	  service_type: z.enum(["logo", "website_update", "data_export", "consulting", "other"]),
88	  title: z.string().trim().min(2, "title too short").max(160, "title too long"),
89	  description: z.string().trim().max(8000).optional().nullable(),
90	  attachments: z
91	    .array(
92	      z.object({
93	        filename: z.string().min(1).max(255),
94	        mime_type: z.string().min(1).max(127),
95	        size_bytes: z.number().int().nonnegative()
96	      })
97	    )
98	    .max(8, "too many attachments")
99	    .optional()
100	});
101	
102	export type SubmitWorkOrderInput = z.infer<typeof submitInput>;
103	
104	export type ActionResult<T> = { ok: true; data: T } | { ok: false; error: string };
105	
106	const ADMIN_NOTIFY_TO = (): string =>
107	  process.env.RESEND_REPLY_TO ?? "jeremyw@dobeu.net";
108	
109	/** One signed upload target the client PUTs bytes to, then finalizes. */
110	export interface UploadTarget {
111	  storage_path: string;
112	  token: string;
113	  filename: string;
114	  mime_type: string;
115	  size_bytes: number;
116	}
117	
118	export async function submitWorkOrder(
119	  raw: unknown
120	): Promise<ActionResult<{ id: string; uploadPaths: string[]; uploadTargets: UploadTarget[] }>> {
121	  const parsed = submitInput.safeParse(raw);
122	  if (!parsed.success) {
123	    return { ok: false, error: parsed.error.issues.map((i) => i.message).join("; ") };
124	  }
125	  const input = parsed.data;
126	
127	  for (const att of input.attachments ?? []) {
128	    if (att.size_bytes > MAX_FILE_SIZE_BYTES) {
129	      return { ok: false, error: `attachment "${att.filename}" exceeds 25 MB cap` };
130	    }
131	    if (!ALLOWED_MIME.has(att.mime_type)) {
132	      return { ok: false, error: `attachment "${att.filename}" mime ${att.mime_type} not allowed` };
133	    }
134	  }
135	
136	  let user, supabase;
137	  try {
138	    ({ user, supabase } = await requireUser());
139	  } catch (e) {
140	    if (e instanceof AuthError) return { ok: false, error: e.code };
141	    throw e;
142	  }
143	
144	  const { data: inserted, error: insertErr } = await supabase
145	    .from("work_orders")
146	    .insert({
147	      created_by: user.id,
148	      service_type: input.service_type,
149	      title: input.title,
150	      description: input.description ?? null,
151	      status: "open"
152	    })
153	    .select("id")
154	    .single();
155	
156	  if (insertErr || !inserted) {
157	    return { ok: false, error: insertErr?.message ?? "insert failed" };
158	  }
159	
160	  const workOrderId = inserted.id;
161	  const uploadPaths: string[] = [];
162	  const uploadTargets: UploadTarget[] = [];
163	
164	  // Mint a signed upload URL per attachment using the SERVICE-ROLE client.
165	  // Ownership is already established (requireUser + the WO insert above) and
166	  // the signed token itself authorizes the client's subsequent PUT — minting
167	  // via admin sidesteps any sign-time RLS evaluation of the storage INSERT
168	  // policy, so a freshly-created WO can never fail to mint for a policy reason.
169	  // The path is `<work_order_id>/...` which also satisfies that policy at PUT
170	  // time. NO attachment row is inserted here — the client PUTs the bytes, then
171	  // calls `finalizeWorkOrderAttachment` (cookie-bound, RLS-enforced) to insert
172	  // the row. Row-after-bytes keeps signed-download links from 404ing.
173	  const storageAdmin = createAdminClient();
174	  for (const att of input.attachments ?? []) {
175	    const storagePath = `${workOrderId}/${crypto.randomUUID()}-${att.filename}`;
176	    const { data: signed, error: signErr } = await storageAdmin.storage
177	      .from("work-order-attachments")
178	      .createSignedUploadUrl(storagePath);
179	    if (signErr || !signed) {
180	      console.warn(
181	        "[submitWorkOrder] signed upload URL failed for",
182	        att.filename,
183	        signErr?.message
184	      );
185	      continue;
186	    }
187	    uploadPaths.push(storagePath);
188	    uploadTargets.push({
189	      storage_path: storagePath,
190	      [REDACTED],
191	      filename: att.filename,
192	      mime_type: att.mime_type,
193	      size_bytes: att.size_bytes
194	    });
195	  }
196	
197	  const profileEmail = user.email ?? "(no email)";
198	  const profileName =
199	    (user.user_metadata as { full_name?: string } | null)?.full_name ?? null;
200	
201	  // Resend admin notification (non-fatal).
202	  try {
203	    const tpl = workOrderReceivedToAdmin({
204	      workOrder: {
205	        id: workOrderId,
206	        title: input.title,
207	        service_type: input.service_type,
208	        description: input.description ?? null
209	      },
210	      client: { email: profileEmail, name: profileName }
211	    });
212	    await sendEmail({
213	      to: ADMIN_NOTIFY_TO(),
214	      subject: tpl.subject,
215	      text: tpl.text,
216	      html: tpl.html
217	    });
218	  } catch (e) {
219	    console.warn("[submitWorkOrder] admin notify failed (non-fatal):", e);
220	  }
221	
222	  // Emit a best-effort `work_order_created` event (non-fatal — mirrors
223	  // processLead's discipline; a failure here must never drop the work order).
224	  //
225	  // NOTE: there is no server-side Intercom event helper in this codebase
226	  // (lib/intercom.ts is the client-side Messenger SDK only). Customer.io is
227	  // the established server-side event channel (lib/customerio.ts, used by the
228	  // lead pipeline), so the event lands there. If/when a server Intercom event
229	  // API is added, point this at it instead.
230	  try {
231	    if (user.email && isCustomerIoConfigured()) {
232	      const res = await cioTrack({
233	        email: user.email,
234	        name: "work_order_created",
235	        data: {
236	          work_order_id: workOrderId,
237	          title: input.title,
238	          service_type: input.service_type
239	        }
240	      });
241	      if (!res.ok) {
242	        console.warn("[submitWorkOrder] work_order_created event failed (non-fatal):", res.error);
243	      }
244	    }
245	  } catch (e) {
246	    console.warn("[submitWorkOrder] work_order_created event threw (non-fatal):", e);
247	  }
248	
249	  revalidatePath("/portal");
250	  revalidatePath("/portal/tickets");
251	  revalidatePath("/admin");
252	  revalidatePath("/admin/tickets");
253	  return { ok: true, data: { id: workOrderId, uploadPaths, uploadTargets } };
254	}
255	
256	const finalizeAttachmentInput = z.object({
257	  work_order_id: uuid,
258	  storage_path: z.string().min(1).max(512),
259	  filename: z.string().min(1).max(255),
260	  mime_type: z.string().min(1).max(127),
261	  size_bytes: z.number().int().nonnegative()
262	});
263	
264	/**
265	 * Insert the `work_order_attachments` row AFTER the client has PUT the bytes
266	 * to the signed upload URL minted by `submitWorkOrder`. RLS (`wo_att_insert_own`)
267	 * ensures the caller owns the work order, and the storage_path is re-validated
268	 * to live under `<work_order_id>/` so a row can't point outside the WO's
269	 * namespace. Re-validates size + MIME (defense in depth).
270	 */
271	export async function finalizeWorkOrderAttachment(
272	  raw: unknown
273	): Promise<ActionResult<{ id: string }>> {
274	  const parsed = finalizeAttachmentInput.safeParse(raw);
275	  if (!parsed.success) {
276	    return { ok: false, error: parsed.error.issues.map((i) => i.message).join("; ") };
277	  }
278	  const input = parsed.data;
279	
280	  if (input.size_bytes > MAX_FILE_SIZE_BYTES) {
281	    return { ok: false, error: `attachment "${input.filename}" exceeds 25 MB cap` };
282	  }
283	  if (!ALLOWED_MIME.has(input.mime_type)) {
284	    return { ok: false, error: `attachment "${input.filename}" mime ${input.mime_type} not allowed` };
285	  }
286	  if (!input.storage_path.startsWith(`${input.work_order_id}/`)) {
287	    return { ok: false, error: "storage_path outside work-order namespace" };
288	  }
289	
290	  let supabase;
291	  try {
292	    ({ supabase } = await requireUser());
293	  } catch (e) {
294	    if (e instanceof AuthError) return { ok: false, error: e.code };
295	    throw e;
296	  }
297	
298	  const { data, error } = await supabase
299	    .from("work_order_attachments")
300	    .insert({
301	      work_order_id: input.work_order_id,
302	      storage_path: input.storage_path,
303	      filename: input.filename,
304	      mime_type: input.mime_type,
305	      size_bytes: input.size_bytes
306	    })
307	    .select("id")
308	    .single();
309	
310	  if (error || !data) return { ok: false, error: error?.message ?? "attachment insert failed" };
311	
312	  revalidatePath(`/portal/tickets/${input.work_order_id}`);
313	  revalidatePath(`/admin/tickets/${input.work_order_id}`);
314	  return { ok: true, data: { id: data.id } };
315	}
316	
317	const quoteInput = z.object({
318	  id: uuid,
319	  amount_cents: positiveInt
320	});
321	
322	export async function quoteWorkOrder(
323	  raw: unknown
324	): Promise<ActionResult<{ id: string }>> {
325	  const parsed = quoteInput.safeParse(raw);
326	  if (!parsed.success) {
327	    return { ok: false, error: parsed.error.issues.map((i) => i.message).join("; ") };
328	  }
329	  const { id, amount_cents } = parsed.data;
330	
331	  let admin;
332	  try {
333	    ({ admin } = await requireAdmin());
334	  } catch (e) {
335	    if (e instanceof AuthError) return { ok: false, error: e.code };
336	    throw e;
337	  }
338	
339	  // Read current status first — a quote is only legal from `open` (open→quoted).
340	  // Without this guard a closed/cancelled work order could be resurrected.
341	  const { data: current, error: readErr } = await admin
342	    .from("work_orders")
343	    .select("status")
344	    .eq("id", id)
345	    .single();
346	  if (readErr || !current) return { ok: false, error: readErr?.message ?? "work order not found" };
347	  if (!canTransition(current.status as WorkOrderStatus, "quoted")) {
348	    return { ok: false, error: `cannot quote from status "${current.status}"` };
349	  }
350	
351	  const { data, error } = await admin
352	    .from("work_orders")
353	    .update({
354	      status: "quoted",
355	      quoted_amount_cents: amount_cents,
356	      quoted_at: new Date().toISOString()
357	    })
358	    .eq("id", id)
359	    .select("id,title,service_type,created_by")
360	    .single();
361	
362	  if (error || !data) return { ok: false, error: error?.message ?? "update failed" };
363	
364	  // Email the work-order owner that a quote is ready.
365	  try {
366	    const recipient = await resolveOwnerEmail(admin, data.created_by);
367	    if (recipient) {
368	      const tpl = workOrderQuoteSentToClient({
369	        workOrder: { id: data.id, title: data.title, service_type: data.service_type },
370	        amountCents: amount_cents
371	      });
372	      await sendEmail({
373	        to: recipient,
374	        subject: tpl.subject,
375	        text: tpl.text,
376	        html: tpl.html
377	      });
378	    }
379	  } catch (e) {
380	    console.warn("[quoteWorkOrder] client email failed (non-fatal):", e);
381	  }
382	
383	  revalidatePath("/admin/tickets");
384	  revalidatePath("/portal/tickets");
385	  return { ok: true, data: { id: data.id } };
386	}
387	
388	const acceptInput = z.object({ id: uuid });
389	
390	export async function acceptWorkOrderQuote(
391	  raw: unknown
392	): Promise<ActionResult<{ id: string; invoice_id: string | null }>> {
393	  const parsed = acceptInput.safeParse(raw);
394	  if (!parsed.success) {
395	    return { ok: false, error: parsed.error.issues.map((i) => i.message).join("; ") };
396	  }
397	  const { id } = parsed.data;
398	
399	  let user, supabase;
400	  try {
401	    ({ user, supabase } = await requireUser());
402	  } catch (e) {
403	    if (e instanceof AuthError) return { ok: false, error: e.code };
404	    throw e;
405	  }
406	
407	  const { data: existing, error: readErr } = await supabase
408	    .from("work_orders")
409	    .select("id,created_by,status,quoted_amount_cents,title")
410	    .eq("id", id)
411	    .single();
412	
413	  if (readErr || !existing) return { ok: false, error: "work order not found" };
414	  if (existing.created_by !== user.id) return { ok: false, error: "forbidden" };
415	  if (existing.status !== "quoted") {
416	    return { ok: false, error: `cannot accept from status "${existing.status}"` };
417	  }
418	  if (!existing.quoted_amount_cents || existing.quoted_amount_cents <= 0) {
419	    return { ok: false, error: "work order has no quote amount" };
420	  }
421	
422	  const { error: flipErr } = await supabase
423	    .from("work_orders")
424	    .update({ status: "accepted", accepted_at: new Date().toISOString() })
425	    .eq("id", id);
426	
427	  if (flipErr) return { ok: false, error: flipErr.message };
428	
429	  // Email admin that the quote was accepted (non-fatal). This is the cue for
430	  // the admin to issue the Stripe invoice from /admin/tickets/[id].
431	  try {
432	    const tpl = workOrderAcceptedToAdmin({
433	      workOrder: { id: existing.id, title: existing.title, service_type: "" }
434	    });
435	    await sendEmail({
436	      to: ADMIN_NOTIFY_TO(),
437	      subject: tpl.subject,
438	      text: tpl.text,
439	      html: tpl.html
440	    });
441	  } catch (e) {
442	    console.warn("[acceptWorkOrderQuote] admin notify failed (non-fatal):", e);
443	  }
444	
445	  // Invoice creation is intentionally NOT triggered here — the admin issues
446	  // the Stripe invoice explicitly via `createInvoiceForWorkOrder`. `invoice_id`
447	  // stays null until then. (Kept in the return shape for the AcceptQuoteForm
448	  // consumer, which is outside this lane.)
449	  revalidatePath("/portal/tickets");
450	  revalidatePath("/admin/tickets");
451	  return { ok: true, data: { id, invoice_id: null } };
452	}
453	
454	const updateStatusInput = z.object({
455	  id: uuid,
456	  status: z.enum(["in_progress", "delivered", "closed", "cancelled"])
457	});
458	
459	export async function updateWorkOrderStatus(
460	  raw: unknown
461	): Promise<ActionResult<{ id: string; status: WorkOrderStatus }>> {
462	  const parsed = updateStatusInput.safeParse(raw);
463	  if (!parsed.success) {
464	    return { ok: false, error: parsed.error.issues.map((i) => i.message).join("; ") };
465	  }
466	  const { id, status } = parsed.data;
467	
468	  let admin;
469	  try {
470	    ({ admin } = await requireAdmin());
471	  } catch (e) {
472	    if (e instanceof AuthError) return { ok: false, error: e.code };
473	    throw e;
474	  }
475	
476	  // Read current status and enforce the transition (the Zod enum only checks
477	  // the target is a valid status, not that open→...→target is legal).
478	  const { data: current, error: readErr } = await admin
479	    .from("work_orders")
480	    .select("status")
481	    .eq("id", id)
482	    .single();
483	  if (readErr || !current) return { ok: false, error: readErr?.message ?? "work order not found" };
484	  if (!canTransition(current.status as WorkOrderStatus, status)) {
485	    return { ok: false, error: `illegal transition "${current.status}" → "${status}"` };
486	  }
487	
488	  // Stamp the per-status timestamp so the client timeline can render it.
489	  const now = new Date().toISOString();
490	  const stamp: Record<string, string> = { status };
491	  if (status === "in_progress") stamp.in_progress_at = now;
492	  else if (status === "delivered") stamp.delivered_at = now;
493	  else if (status === "closed") stamp.closed_at = now;
494	  else if (status === "cancelled") stamp.cancelled_at = now;
495	
496	  const { data, error } = await admin
497	    .from("work_orders")
498	    // Cast: the `*_at` columns land in lib/database.types.ts via the central
499	    // `pnpm db:types` regen (migration 20260618000000); stale types until then.
500	    // eslint-disable-next-line @typescript-eslint/no-explicit-any
501	    .update(stamp as any)
502	    .eq("id", id)
503	    .select("id,title,service_type,created_by")
504	    .single();
505	
506	  if (error || !data) return { ok: false, error: error?.message ?? "update failed" };
507	
508	  // Email the owner about the status change (in_progress/delivered/closed/cancelled).
509	  try {
510	    const recipient = await resolveOwnerEmail(admin, data.created_by);
511	    if (recipient) {
512	      const tpl = workOrderStatusChangedToClient({
513	        workOrder: { id: data.id, title: data.title, service_type: data.service_type },
514	        newStatus: status
515	      });
516	      await sendEmail({
517	        to: recipient,
518	        subject: tpl.subject,
519	        text: tpl.text,
520	        html: tpl.html
521	      });
522	    }
523	  } catch (e) {
524	    console.warn("[updateWorkOrderStatus] client email failed (non-fatal):", e);
525	  }
526	
527	  revalidatePath("/admin/tickets");
528	  revalidatePath("/portal/tickets");
529	  return { ok: true, data: { id, status } };
530	}
531	
532	/**
533	 * Resolve a work-order owner's email via service-role admin client.
534	 * Returns null (don't throw) on lookup failure so emails stay non-fatal.
535	 */
536	async function resolveOwnerEmail(
537	  admin: { auth: { admin: { getUserById: (id: string) => Promise<{ data: { user: { email?: string | null } | null } | null }> } } },
538	  userId: string
539	): Promise<string | null> {
540	  try {
541	    const { data } = await admin.auth.admin.getUserById(userId);
542	    return data?.user?.email ?? null;
543	  } catch (e) {
544	    console.warn("[resolveOwnerEmail] lookup failed:", e);
545	    return null;
546	  }
547	}
